"""Test the two opposite-port assignments simultaneously, with and without the B mark; no Hall poles or affine chart."""
from itertools import permutations
rows=('BRNN','BNRN');V=range(4);g=(0,2,1,3);blocks=[(frozenset(i for i,c in enumerate(w) if c in 'BR'),frozenset(i for i,c in enumerate(w) if c=='N')) for w in rows];f=[tuple(next(iter(side-{i})) for i in V for side in b if i in side) for b in blocks];G=[p for p in permutations(V) if all(p[h[i]]==h[p[i]] for h in [*f,g] for i in V)];marked=[p for p in G if p[0]==0];ex=[p for p in G if all({p[i] for i in b}==n for b,n in blocks)];assert G==[(0,1,2,3),(3,2,1,0)] and ex==G[1:] and marked==G[:1];print('exchange preserving both opposite rules and row relabeling:',tuple(i+1 for i in ex[0]),'; B-marked stabilizer size',len(marked))
